class MKAverage {
    private static final int LIMIT = 100_000;

    private final int m;
    private final int k;
    private final int[] window;
    private final int[] counts = new int[LIMIT + 1];
    private final long[] sums = new long[LIMIT + 1];

    private int size;
    private int nextIndex;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.window = new int[m];
    }

    public void addElement(int num) {
        if (size == m) {
            update(window[nextIndex], -1);
        } else {
            size++;
        }

        window[nextIndex] = num;
        nextIndex = (nextIndex + 1) % m;
        update(num, 1);
    }

    public int calculateMKAverage() {
        if (size < m) {
            return -1;
        }

        long middleSum = sumSmallest(m - k) - sumSmallest(k);
        return (int) (middleSum / (m - 2 * k));
    }

    private void update(int value, int delta) {
        for (int i = value; i <= LIMIT; i += i & -i) {
            counts[i] += delta;
            sums[i] += (long) value * delta;
        }
    }

    // Returns the sum of the smallest rank elements, including duplicates.
    private long sumSmallest(int rank) {
        int index = 0;
        int taken = 0;
        long sum = 0;

        // Find the value containing the rank-th element using Fenwick lifting.
        for (int step = Integer.highestOneBit(LIMIT); step > 0; step >>= 1) {
            int next = index + step;
            if (next <= LIMIT && taken + counts[next] < rank) {
                index = next;
                taken += counts[next];
                sum += sums[next];
            }
        }

        return sum + (long) (rank - taken) * (index + 1);
    }
}

